-- Extends the G4 publication fixture inside its open rollback transaction.
reset role;
select pg_temp.pu_assert(to_regprocedure('public.get_game_occurrence_state(uuid,integer)') is not null,'occurrence state RPC exists');
select pg_temp.pu_assert(to_regprocedure('public.save_game_occurrence(jsonb)') is not null,'occurrence writer exists');
select pg_temp.pu_assert(to_regprocedure('public.get_game_occurrence_version(uuid,integer)') is not null,'occurrence version reader exists');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(98)::text,true);
select pg_temp.pu_assert(public.get_game_occurrence_state(pg_temp.pu_id(8))->'head'='null'::jsonb,'new game has no invented decision');
reset role;
select 'game occurrences contract PASS' as result;
-- Run with G4 and R3 fixture data, never commit it.
create function pg_temp.oc_command(n integer,base integer default 0,e jsonb default '{"kind":"postponed"}'::jsonb,gid uuid default pg_temp.pu_id(8)) returns jsonb language plpgsql as $$declare s jsonb;begin
 s:=public.get_game_occurrence_state(gid);
 return jsonb_build_object('commandId',pg_temp.pu_id(10000+n),'disputeId',s->'disputeId','gameId',gid,'occurrenceId',coalesce(s#>'{head,id}',to_jsonb(pg_temp.pu_id(1000+n))),'expectedVersion',base,'expectedGameVersion',s->'gameVersion','expectedPublicationVersion',s->'publicationVersion','expectedRegulationVersion',s->'regulationVersion','expectedContextFingerprint',s->'contextFingerprint','effect',e,'reason','Ocorrência conferida com o contexto atual','acknowledgeImpact',true);
end$$;
grant execute on function pg_temp.oc_command(integer,integer,jsonb,uuid) to authenticated;
set local role anon;
select pg_temp.pu_error('select public.get_game_occurrence_state(pg_temp.pu_id(8))','42501');
select pg_temp.pu_error('select public.save_game_occurrence(''{}'')','42501');
set local role service_role;
select pg_temp.pu_error('select public.get_game_occurrence_state(pg_temp.pu_id(8))','42501');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(99)::text,true);
select pg_temp.pu_error('select public.get_game_occurrence_state(pg_temp.pu_id(8))','PT403');
select pg_temp.pu_error('select public.save_game_occurrence(''{}'')','PT403');
select set_config('request.jwt.claim.sub',pg_temp.pu_id(98)::text,true);
select pg_temp.pu_error('select * from private.game_occurrence_heads','42501');
select pg_temp.pu_error('select public.get_game_occurrence_state(pg_temp.pu_id(999))','PT404');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||''{"actorId":"forged"}''::jsonb)','PT400');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||''{"reason":" "}''::jsonb)','PT400');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||''{"acknowledgeImpact":false}''::jsonb)','PT400');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||''{"expectedGameVersion":1}''::jsonb)','PT409');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||''{"expectedPublicationVersion":0}''::jsonb)','PT409');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||''{"expectedRegulationVersion":0}''::jsonb)','PT409');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||jsonb_build_object(''expectedContextFingerprint'',repeat(''b'',64)))','PT409');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1)||jsonb_build_object(''disputeId'',pg_temp.pu_id(605)))','PT400');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1,0,''null''::jsonb))','PT400');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(1,0,jsonb_build_object(''kind'',''wo'',''winnerRegistrationId'',pg_temp.pu_id(5))))','PT400');
reset role;
create temp table oc_frozen(label text primary key,command jsonb);
grant select on oc_frozen to authenticated;
insert into oc_frozen values('first',pg_temp.oc_command(1));
set local role authenticated;
select pg_temp.pu_assert(public.save_game_occurrence((select command from oc_frozen where label='first'))->'version'='1','occurrence1 saved');
select pg_temp.pu_assert(public.save_game_occurrence((select command from oc_frozen where label='first'))->'version'='1','identical lost ACK replay');
select pg_temp.pu_error('select public.save_game_occurrence((select command from oc_frozen where label=''first'')||''{"reason":"Changed payload"}''::jsonb)','PT409');
select pg_temp.pu_assert(public.get_game_occurrence_state(pg_temp.pu_id(8))#>>'{head,effect,kind}'='postponed','saved explicit postponement');
select pg_temp.pu_assert(public.get_regulation_state(pg_temp.pu_id(3))#>'{context,decisionVersion}'='1','head revision enters fingerprint');
select pg_temp.pu_assert(jsonb_array_length(public.get_regulation_state(pg_temp.pu_id(3))#>'{context,occurrences}')=1,'active competitive effect is in minimal context');
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(8))#>'{facts,teams,home,points}'='3','source score not rewritten');
reset role;
select pg_temp.pu_assert((select count(*) from private.game_occurrence_versions)=1,'replay did not create extra version');
select pg_temp.pu_error('update private.game_occurrence_versions set reason=''Changed''','PT409');
select pg_temp.pu_error($q$insert into private.game_occurrence_versions select (jsonb_populate_record(null::private.game_occurrence_versions,(select to_jsonb(v) from private.game_occurrence_versions v limit 1)||'{"version":99,"reason":"  "}'::jsonb)).*$q$,'23514');
select pg_temp.pu_error('delete from private.game_occurrence_heads','PT409');
select pg_temp.pu_error('delete from private.game_occurrence_records','PT409');
update public.championships set saved_at='2001-01-01T00:00:00Z' where id=pg_temp.pu_id(1);
set local role authenticated;
select public.get_game_occurrence_state(pg_temp.pu_id(8));
select public.get_game_occurrence_version(pg_temp.pu_id(8),1);
select public.save_game_occurrence((select command from oc_frozen where label='first'));
reset role;
select pg_temp.pu_assert((select saved_at='2001-01-01T00:00:00Z' from public.championships where id=pg_temp.pu_id(1)),'reads and replay preserve Recentes');
insert into oc_frozen values('failure',pg_temp.oc_command(55,1,'{"kind":"administrative","decision":{"kind":"exclude"}}'));
create function pg_temp.oc_failure() returns trigger language plpgsql as $$begin raise exception 'injected occurrence receipt failure';end$$;
create trigger occurrence_fixture_failure before insert on private.game_occurrence_commands for each row execute function pg_temp.oc_failure();
set local role authenticated;
select pg_temp.pu_error('select public.save_game_occurrence((select command from oc_frozen where label=''failure''))','P0001');
select pg_temp.pu_assert(public.get_game_occurrence_state(pg_temp.pu_id(8))#>'{head,version}'='1','receipt failure rolls back head');
reset role;
select pg_temp.pu_assert((select count(*) from private.game_occurrence_versions)=1,'receipt failure rolls back history');
select pg_temp.pu_assert((select saved_at='2001-01-01T00:00:00Z' from public.championships where id=pg_temp.pu_id(1)),'receipt failure rolls back Recentes');
drop trigger occurrence_fixture_failure on private.game_occurrence_commands;
set local role authenticated;
select pg_temp.pu_assert(public.save_game_occurrence((select command from oc_frozen where label='failure'))->'version'='2','same failed command succeeds after transient problem');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(4,1))','PT409');
select pg_temp.pu_assert(public.save_game_occurrence(pg_temp.oc_command(3,2,'null'))->'version'='3','explicit removal is another version');
select pg_temp.pu_assert(public.get_game_occurrence_state(pg_temp.pu_id(8))#>'{head,effect}'='null','inactive head retained');
select pg_temp.pu_assert(public.get_regulation_state(pg_temp.pu_id(3))#>'{context,decisionVersion}'='3','inactive head still changes source fingerprint');
select pg_temp.pu_assert(jsonb_array_length(public.get_regulation_state(pg_temp.pu_id(3))#>'{context,occurrences}')=0,'removed effect no longer applies');
select pg_temp.pu_assert(public.get_game_occurrence_version(pg_temp.pu_id(8),1)#>>'{effect,kind}'='postponed','previous effect remains in history');
select pg_temp.pu_assert(jsonb_array_length(public.get_game_occurrence_state(pg_temp.pu_id(8),20)->'history')=0,'paged occurrence history');
select pg_temp.pu_assert(public.get_game_occurrence_version(pg_temp.pu_id(8),999) is null,'missing version not fabricated');
select pg_temp.pu_assert(public.save_game_occurrence(pg_temp.oc_command(4,3))->'version'='4','reactivation is explicit');
reset role;
insert into oc_frozen values('source_changed',pg_temp.oc_command(60,4));
-- G4 source correction is still possible and does not rewrite the administrative decision.
set local role authenticated;
select pg_temp.pu_assert(public.publish_sheet_game(pg_temp.pu_command(80)||jsonb_build_object('gameVersion',(public.get_game(pg_temp.pu_id(8))->>'version')::integer,'basePublicationVersion',(public.get_public_game(pg_temp.pu_id(8))->>'version')::integer,'source',jsonb_build_object('kind','sheet','baseSheetVersion',(public.get_game_sheet(pg_temp.pu_id(8))->>'version')::integer,'document',jsonb_set(pg_temp.pu_doc(),'{events,0,code}','"2"')),'reason','Nova conferência do placar da partida.'))->'version'='3','G4 correction preserves independent occurrence');
select pg_temp.pu_error('select public.save_game_occurrence((select command from oc_frozen where label=''source_changed''))','PT409');
select pg_temp.pu_assert(public.get_game_occurrence_state(pg_temp.pu_id(8))#>'{head,publicationVersion}'='2','old source version remains recorded for review');
select public.get_game_occurrence_state(pg_temp.pu_id(8)) as occurrence_state;
select public.get_game_occurrence_version(pg_temp.pu_id(8),1) as occurrence_version;
select public.get_regulation_state(pg_temp.pu_id(3)) as regulation_state;
reset role;
