-- Configure a real WO rule using the existing versioned regulation writer.
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(98)::text,true);
select pg_temp.pu_assert(public.save_regulation(pg_temp.rg_command(30,2)||jsonb_build_object('definition',jsonb_set(public.get_regulation_state(pg_temp.pu_id(3))->'definition','{occurrenceRules,wo}','{"winnerLeaguePoints":2,"loserLeaguePoints":-1,"score":{"winner":20,"loser":0}}')))->'version'='3','WO rule configured explicitly');
select pg_temp.pu_assert(public.save_game_occurrence(pg_temp.oc_command(40,0,jsonb_build_object('kind','wo','winnerRegistrationId',pg_temp.pu_id(5)),pg_temp.pu_id(600)))->'version'='1','WO on scheduled game creates no played fact');
select pg_temp.pu_assert(public.save_regulation(pg_temp.rg_command(31,3)||jsonb_build_object('definition',jsonb_set(public.get_regulation_state(pg_temp.pu_id(3))->'definition','{occurrenceRules,wo}','null')))->'version'='4','removing WO rule preserves earlier decision for explicit review');
select public.get_regulation_state(pg_temp.pu_id(3)) as missing_wo_rule_state;
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(41,1,jsonb_build_object(''kind'',''wo'',''winnerRegistrationId'',pg_temp.pu_id(5)),pg_temp.pu_id(600)))','PT400');
select pg_temp.pu_assert(public.save_regulation(pg_temp.rg_command(32,4)||jsonb_build_object('definition',jsonb_set(public.get_regulation_state(pg_temp.pu_id(3))->'definition','{occurrenceRules,wo}','{"winnerLeaguePoints":2,"loserLeaguePoints":-1,"score":null}')))->'version'='5','restored rule remains an explicit version');
select pg_temp.pu_error('select public.save_game_occurrence(pg_temp.oc_command(41,1,jsonb_build_object(''kind'',''wo'',''winnerRegistrationId'',pg_temp.pu_id(606)),pg_temp.pu_id(600)))','PT400');
select pg_temp.pu_error($q$select public.save_game_occurrence(pg_temp.oc_command(41,1,jsonb_build_object('kind','administrative','decision',jsonb_build_object('kind','award','winnerRegistrationId',pg_temp.pu_id(604),'homeLeaguePoints',2,'awayLeaguePoints',0,'score',jsonb_build_object('homePoints',20,'awayPoints',0))),pg_temp.pu_id(600)))$q$,'PT400');
select pg_temp.pu_assert(public.save_game_occurrence(pg_temp.oc_command(41,1,jsonb_build_object('kind','administrative','decision',jsonb_build_object('kind','award','winnerRegistrationId',pg_temp.pu_id(604),'homeLeaguePoints',0,'awayLeaguePoints',2,'score',null)),pg_temp.pu_id(600)))->'version'='2','explicit administrative award without invented score');
select pg_temp.pu_assert(public.save_game_occurrence(pg_temp.oc_command(42,2,'{"kind":"interrupted"}',pg_temp.pu_id(600)))->'version'='3','interruption is explicit');
select pg_temp.pu_assert(public.save_game_occurrence(pg_temp.oc_command(43,3,'{"kind":"cancelled"}',pg_temp.pu_id(600)))->'version'='4','cancellation is explicit');
select pg_temp.pu_assert(public.get_public_game(pg_temp.pu_id(600)) is null,'no fake 0-0 public game from WO or administrative award');
select pg_temp.pu_assert(public.get_game_occurrence_state(pg_temp.pu_id(8))#>'{head,version}'='4','other game untouched by this operation');
select pg_temp.pu_assert(public.save_game_occurrence(pg_temp.oc_command(44,0,'{"kind":"postponed"}',pg_temp.pu_id(607)))->'version'='1','postponement works before any regulation exists');
select public.get_game_occurrence_state(pg_temp.pu_id(600)) as additional_occurrence_state;
reset role;
select pg_temp.rg_restrict('delete from public.games where id=pg_temp.pu_id(607)','game_occurrence_records_game_id_dispute_id_fkey');
select pg_temp.pu_assert((select count(*) from public.published_games)=2,'administrative writers do not publish incidental drafts');
select pg_temp.pu_assert((select count(*) from private.game_publication_versions)=4,'only the explicit G4 correction added source history');
select 'all competitive occurrence kinds PASS' as result;

